const dest="Earth Orbit", distKm=420, c=299792458;
const lightS=distKm*1000/c;
console.log("Destination: " + dest);
console.log("Distance (km): " + distKm.toLocaleString("en-US"));
console.log("One-way light-time (s): " + lightS.toFixed(2));
console.log("Travel time at 0.1c: " + (distKm*1000/(0.1*c)/86400).toFixed(2) + " days");
console.log("Time dilation at 0.1c (gamma): " + (1/Math.sqrt(1-0.01)).toFixed(4));
console.log("FTL: not offered; c is the limit.");

